        at least 2 more than the opponent, and that player wins the set 7-6.
        Set 3 has no tiebreak: games continue until a player is 2 games ahead (for example
        8-6 or 12-10).
        Match: the first player to win 2 sets wins the match.

    Returns (state, score):
        state is "A won", "B won" or "in progress".
        score is a str of parts separated by single spaces. Every pair of numbers is
        written as A's number, "-", B's number.
          - One part per completed set: its games, e.g. "6-4". A set decided by a tiebreak
            also shows the set loser's tiebreak points in parentheses: "7-6(5)" means A
            won the tiebreak 7-5; "6-7(10)" means B won it 12-10.
          - If the match is in progress, two more parts follow: the current set's games
            (e.g. "0-0" at the start of a set, "6-6" before a tiebreak), then the current
            game's points:
              - In a normal game, each player's points are named 0, 15, 30, 40 for 0, 1, 2,
                3 points, e.g. "0-0", "30-15" or "40-0". When both players have at least 3
                points, the game is instead "deuce" if they are level, or "advantage A" /
                "advantage B" for the player one point ahead.
              - In a tiebreak (from the moment the set reaches 6-6), the game is
                "tiebreak " followed by the plain point counts, e.g. "tiebreak 0-0" or
                "tiebreak 5-3".
        Examples: [] gives ("in progress", "0-0 0-0"); A winning the first set 6-4 and
        then the first point of set 2 gives ("in progress", "6-4 0-0 15-0"); a finished
        match lists only its sets, e.g. ("A won", "6-4 7-6(3)").
    """
    if isinstance(points, str) or not isinstance(points, (list, tuple)):
        raise TypeError("points must be a list or tuple")

    completed = []  # list of (a_games, b_games, tie_loser_pts or None)
    set_a = 0
    set_b = 0
    game_a = 0
    game_b = 0

    def sets_won(player):
        if player == "A":
            return sum(1 for a, b, _ in completed if a > b)
        return sum(1 for a, b, _ in completed if b > a)

    def match_over():
        return sets_won("A") == 2 or sets_won("B") == 2

    def in_tiebreak():
        return len(completed) < 2 and set_a == 6 and set_b == 6

    for item in points:
        if match_over():
            raise ValueError("point after match has been won")
        if item is not None and type(item) is not str:
            raise ValueError("invalid point winner")
        if item != "A" and item != "B":
            raise ValueError("invalid point winner")

        if in_tiebreak():
            if item == "A":
                game_a += 1
            else:
                game_b += 1
            if (game_a >= 7 or game_b >= 7) and abs(game_a - game_b) >= 2:
                if game_a > game_b:
                    completed.append((7, 6, game_b))
                else:
                    completed.append((6, 7, game_a))
                set_a = 0
                set_b = 0
                game_a = 0
                game_b = 0
        else:
            if item == "A":
                game_a += 1
            else:
                game_b += 1
            if (game_a >= 4 or game_b >= 4) and abs(game_a - game_b) >= 2:
                # game won
                if game_a > game_b:
                    set_a += 1
                else:
                    set_b += 1
                game_a = 0
                game_b = 0
                # check set end
                if set_a == 6 and set_b == 6 and len(completed) < 2:
                    # enter tiebreak, nothing more
                    pass
                else:
                    if len(completed) < 2:
                        if (set_a >= 6 or set_b >= 6) and abs(set_a - set_b) >= 2:
                            completed.append((set_a, set_b, None))
                            set_a = 0
                            set_b = 0
                    else:
                        # third set, no tiebreak
                        if (set_a >= 6 or set_b >= 6) and abs(set_a - set_b) >= 2:
                            completed.append((set_a, set_b, None))
                            set_a = 0
                            set_b = 0

    if sets_won("A") == 2:
        state = "A won"
    elif sets_won("B") == 2:
        state = "B won"
    else:
        state = "in progress"

    parts = []
    for a, b, tie in completed:
        s = f"{a}-{b}"
        if tie is not None:
            s += f"({tie})"
        parts.append(s)

    if state == "in progress":
        parts.append(f"{set_a}-{set_b}")
        if in_tiebreak():
            parts.append(f"tiebreak {game_a}-{game_b}")
        else:
            if game_a >= 3 and game_b >= 3:
                if game_a == game_b:
                    parts.append("deuce")
                elif game_a == game_b + 1:
                    parts.append("advantage A")
                elif game_b == game_a + 1:
                    parts.append("advantage B")
                else:
                    # Should not happen in valid play (game would have ended),
                    # but render fallback.
                    names = {0: "0", 1: "15", 2: "30", 3: "40"}
                    # for extended deuce, cap display
                    parts.append(f"{names.get(game_a, '40')}-{names.get(game_b, '40')}")
            else:
                names = ["0", "15", "30", "40"]
                parts.append(f"{names[game_a]}-{names[game_b]}")

    return (state, " ".join(parts))
